insert into public.categories (slug, name, description, image_url, sort_order, is_active) values
  ('doces-tradicionais', 'Doces Tradicionais', 'Brigadeiros, beijinhos e os clássicos que nunca saem de moda.', 'https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=1000&q=80', 1, true),
  ('doces-gourmet', 'Doces Gourmet', 'Sabores refinados e ingredientes selecionados para os mais exigentes.', 'https://images.unsplash.com/photo-1551103782-5ab3a2a1f74a?auto=format&fit=crop&w=1000&q=80', 2, true),
  ('chocolates', 'Chocolates', 'Trufas, bombons e chocolate nobre derretendo de desejo.', 'https://images.unsplash.com/photo-1587668178277-295251f900ce?auto=format&fit=crop&w=1000&q=80', 3, true),
  ('bolos', 'Bolos', 'Bolos artesanais para aniversários, casamentos e encontros.', 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1000&q=80', 4, true),
  ('presentes', 'Presentes', 'Caixas e cestas prontas para emocionar quem você ama.', 'https://images.unsplash.com/photo-1549007953-2f2dc0b24019?auto=format&fit=crop&w=1000&q=80', 5, true),
  ('festas', 'Festas', 'Mesas doces e kits completos para a sua celebração.', 'https://images.unsplash.com/photo-1563729784474-d77dbb933a9e?auto=format&fit=crop&w=1000&q=80', 6, true);
insert into public.products (category_id, name, slug, description, price, compare_at_price, image_url, gallery, stock, is_active, is_best_seller, sales_count, badges) values
  ((select id from public.categories where slug = 'doces-tradicionais'), 'Brigadeiro Tradicional', 'brigadeiro-tradicional', 'O clássico brasileiro feito com chocolate meio amargo e granulado artesanal. Cada unidade é enrolada na hora para manter a textura cremosa perfeita.', 3.90, null, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1563729784474-d77dbb933a9e?auto=format&fit=crop&w=1000&q=80"]', 200, true, true, 520, '["Mais Vendido"]'),
  ((select id from public.categories where slug = 'doces-tradicionais'), 'Beijinho de Coco', 'beijinho-de-coco', 'Doce de coco fresco com leite condensado, finalizado com cravo da índia. Cremoso e irresistível.', 3.90, null, 'https://images.unsplash.com/photo-1571761970713-4d82cbc39c3c?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1571761970713-4d82cbc39c3c?auto=format&fit=crop&w=1000&q=80"]', 180, true, true, 410, '["Mais Vendido"]'),
  ((select id from public.categories where slug = 'doces-gourmet'), 'Brigadeiro de Nutella', 'brigadeiro-de-nutella', 'Brigadeiro gourmet com recheio cremoso de avelã. Cobertura de chocolate belga em lascas para um final crocante.', 7.50, 9.90, 'https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=1000&q=80"]', 120, true, true, 380, '["Gourmet","Promoção"]'),
  ((select id from public.categories where slug = 'doces-gourmet'), 'Trufa de Pistache', 'trufa-de-pistache', 'Trufa gourmet de pistache italiano com casquinha de chocolate branco. Uma experiência sofisticada de sabor.', 12.90, null, 'https://images.unsplash.com/photo-1626803775151-61d756612a2a?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1626803775151-61d756612a2a?auto=format&fit=crop&w=1000&q=80"]', 80, true, true, 230, '["Gourmet"]'),
  ((select id from public.categories where slug = 'chocolates'), 'Caixa de Trufas Artesanais', 'caixa-de-trufas-artesanais', 'Caixa com 12 trufas sortidas feitas com chocolate nobre 70%. Sabores: maracujá, framboesa, doce de leite e pistache.', 79.90, 94.90, 'https://images.unsplash.com/photo-1548907040-4baa42d10919?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1548907040-4baa42d10919?auto=format&fit=crop&w=1000&q=80","https://images.unsplash.com/photo-1587668178277-295251f900ce?auto=format&fit=crop&w=1000&q=80"]', 40, true, true, 190, '["Promoção"]'),
  ((select id from public.categories where slug = 'chocolates'), 'Bombom de Doce de Leite', 'bombom-de-doce-de-leite', 'Doce de leite mineiro envolto em chocolate ao leite derretido na boca. Embalagem com 10 unidades.', 29.90, null, 'https://images.unsplash.com/photo-1551024506-0bccd828d307?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1551024506-0bccd828d307?auto=format&fit=crop&w=1000&q=80"]', 65, true, true, 150, '[]'),
  ((select id from public.categories where slug = 'bolos'), 'Bolo de Chocolate Artesanal', 'bolo-de-chocolate-artesanal', 'Massa úmida de chocolate meio amargo com cobertura de ganache belga e topo crocante. Serve até 15 pessoas.', 89.90, 109.90, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1000&q=80"]', 12, true, true, 110, '["Promoção"]'),
  ((select id from public.categories where slug = 'bolos'), 'Bolo Red Velvet', 'bolo-red-velvet', 'O queridinho das festas modernas. Massa vermelha aveludada com recheio e cobertura de cream cheese glacê.', 99.90, null, 'https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=1000&q=80"]', 8, true, true, 95, '["Novidade"]'),
  ((select id from public.categories where slug = 'doces-gourmet'), 'Cupcake de Morango', 'cupcake-de-morango', 'Cupcake de baunilha com coração de geleia de morango e buttercream rosé. Unidade delicada e saborosa.', 8.90, null, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=1000&q=80"]', 60, true, false, 140, '[]'),
  ((select id from public.categories where slug = 'presentes'), 'Cesta Presente Doce Amor', 'cesta-presente-doce-amor', 'Cesta com brigadeiros gourmet, trufas, cookie gigante e cartão personalizado. A forma mais doce de presentear.', 149.90, 179.90, 'https://images.unsplash.com/photo-1549007953-2f2dc0b24019?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1549007953-2f2dc0b24019?auto=format&fit=crop&w=1000&q=80"]', 25, true, true, 85, '["Promoção","Mais Vendido"]'),
  ((select id from public.categories where slug = 'festas'), 'Kit Mesa Doce 30 Pessoas', 'kit-mesa-doce-30-pessoas', 'Kit completo para mesa doce: 100 docinhos sortidos, bolo e parte de decoração. Monte a sua festa com a gente.', 349.90, null, 'https://images.unsplash.com/photo-1563729784474-d77dbb933a9e?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1563729784474-d77dbb933a9e?auto=format&fit=crop&w=1000&q=80"]', 10, true, false, 40, '["Sob encomenda"]'),
  ((select id from public.categories where slug = 'festas'), 'Paquera de Docinhos (50un)', 'paquera-de-docinhos-50un', 'Caixa com 50 unidades de docinhos sortidos: brigadeiro, beijinho e cajuzinho. Perfeito para festas e confraternizações.', 89.90, 99.90, 'https://images.unsplash.com/photo-1571761970713-4d82cbc39c3c?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1571761970713-4d82cbc39c3c?auto=format&fit=crop&w=1000&q=80"]', 30, true, true, 76, '["Promoção"]'),
  ((select id from public.categories where slug = 'doces-gourmet'), 'Cookie Artesanal Duo Chocolate', 'cookie-artesanal-duo-chocolate', 'Cookie macio com gotas de chocolate ao leite e meio amargo. Assado na hora, crocante por fora e cremoso por dentro.', 9.90, null, 'https://images.unsplash.com/photo-1621939514649-280e2ee25f60?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1621939514649-280e2ee25f60?auto=format&fit=crop&w=1000&q=80"]', 90, true, false, 120, '[]'),
  ((select id from public.categories where slug = 'chocolates'), 'Ovo de Páscoa Trufado', 'ovo-de-pascoa-trufado', 'Ovo artesanal de chocolate belga trufado, recheado com ganache cremosa. Disponível nas versões ao leite e meio amargo.', 119.90, 139.90, 'https://images.unsplash.com/photo-1606913084603-49e2a1eb6d46?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1606913084603-49e2a1eb6d46?auto=format&fit=crop&w=1000&q=80"]', 20, true, false, 33, '["Promoção"]'),
  ((select id from public.categories where slug = 'doces-tradicionais'), 'Pote de Doce de Leite', 'pote-de-doce-de-leite', 'Doce de leite cremoso produzido artesanalmente. Pote com 320g pronto para passar, rechear ou comer de colher.', 24.90, 29.90, 'https://images.unsplash.com/photo-1621939514649-280e2ee25f60?auto=format&fit=crop&w=1000&q=80', '["https://images.unsplash.com/photo-1621939514649-280e2ee25f60?auto=format&fit=crop&w=1000&q=80"]', 45, true, true, 98, '["Promoção"]');
