  ('Promoções que derretem o coração', 'Aproveite descontos especiais nos nossos doces mais queridos.', 'https://images.unsplash.com/photo-1548907040-4baa42d10919?auto=format&fit=crop&w=1000&q=80', 'Ver Promoções', '/promocoes', 2, true),
